	for _, node := range astFile.TypeSpec {
		if node.Name == "type" {
			break
		}
	}

	typeSpec := astFile.TypeSpec[len(astFile.TypeSpec)-1]
	if typeSpec.Type.Name != "struct" || len(typeSpec.Type.Params) != 1 {
